import type { SystemUser } from './system-user-model';
import type { CTSDocument } from './cts-document-model';

export const CTSDocumentApprovalDecisionKeyToLabel = {
  'Pending': 'Pending',
  'Approved': 'Approved',
  'Rejected': 'Rejected'
} as const;
export type CTSDocumentApprovalDecisionKey = keyof typeof CTSDocumentApprovalDecisionKeyToLabel;

export interface CTSDocumentApproval {
  /**
   * @displayName CTS Document Approval
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Approval Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  approvalName: string;
  /**
   * @displayName Approver
   */
  approver?: Pick<SystemUser, 'id' | 'fullName'>;
  /**
   * @displayName Comments
   */
  comments?: string;
  /**
   * @displayName Decision Date
   */
  decisionDate?: string;
  /**
   * @displayName Decision
   */
  decisionKey?: CTSDocumentApprovalDecisionKey;
  /**
   * @displayName Document
   */
  document?: Pick<CTSDocument, 'id' | 'documentName'>;
}

export const _CTSDocumentApproval = 'CTSDocumentApproval' as const;